// Recibe la pieza completa desde la app (contrato en n8n/claudia-generar.md)
// y emite N items (uno por variante) con el prompt de marca ya construido.
const body = ($input.first().json.body) || {};
const pieza = body.pieza || {};
const ctx = body.contexto || {};
const marca = ctx.marca || {};
const centro = ctx.centro || {};
const linea = ctx.linea || {};
const situacion = ctx.situacion || {};
const brief = pieza.brief || {};
const dir = brief.direccion || {};

const paleta = Array.isArray(marca.paleta)
  ? marca.paleta.map(c => (c && c.nombre ? c.nombre + ' (' + c.hex + ')' : c)).filter(Boolean).join(', ')
  : '';
const reglas = Array.isArray(marca.reglas) ? marca.reglas.map(r => '- ' + r).join('\n') : '';
const ratio = brief.ratio || '1:1';

const basePrompt = [
  pieza.prompt || 'Imagen corporativa del sector salud, sobria y profesional, sin texto.',
  '',
  'Identidad de marca: territorio "' + (marca.territorio || 'Salud Responsable') + '".',
  paleta ? 'Paleta de color de marca: ' + paleta + '.' : '',
  centro.nombre ? 'Centro: ' + centro.nombre + (centro.ciudad ? ' (' + centro.ciudad + ')' : '') + '.' : '',
  linea.nombre ? 'Linea de comunicacion: ' + linea.nombre + '.' : '',
  situacion.nombre ? 'Situacion: ' + situacion.nombre + '.' : '',
  dir.estilo ? 'Estilo: ' + dir.estilo + '.' : '',
  dir.iluminacion ? 'Iluminacion: ' + dir.iluminacion + '.' : '',
  dir.encuadre ? 'Encuadre: ' + dir.encuadre + '.' : '',
  'Relacion de aspecto ' + ratio + '.',
  'IMPORTANTE: la imagen no debe incluir ningun texto, palabra ni logotipo.',
  reglas ? 'Reglas de cumplimiento que respetar:\n' + reglas : '',
  pieza.notas_compliance ? 'Notas de compliance: ' + pieza.notas_compliance : '',
].filter(Boolean).join('\n');

// Cuantas variantes: la app manda brief.variantes (2, 4 o 6). Acotado a 1..6.
const n = Math.min(Math.max(parseInt(brief.variantes, 10) || 1, 1), 6);
const stamp = Date.now();
const hints = ['composicion equilibrada', 'plano mas cercano', 'angulo lateral', 'plano general amplio', 'enfoque en un detalle', 'perspectiva elevada'];

const out = [];
for (let i = 0; i < n; i++) {
  out.push({
    json: {
      prompt: basePrompt + '\nVariacion ' + (i + 1) + ' de ' + n + ': ' + (hints[i] || 'composicion alternativa') + '.',
      promptOriginal: pieza.prompt || null,
      storagePath: 'piezas/' + stamp + '-' + i + '-' + Math.floor(Math.random() * 1000000) + '.png',
      titulo: (pieza.titulo || 'Pieza generada') + (n > 1 ? ' V' + (i + 1) : ''),
      centro_id: pieza.centro_id != null ? pieza.centro_id : null,
      carpeta_id: pieza.carpeta_id != null ? pieza.carpeta_id : null,
      situacion_id: pieza.situacion_id != null ? pieza.situacion_id : null,
      linea_id: pieza.linea_id != null ? pieza.linea_id : null,
      estado: pieza.estado || 'borrador',
      fecha_publicacion: pieza.fecha_publicacion != null ? pieza.fecha_publicacion : null,
      canal: pieza.canal != null ? pieza.canal : null,
      consentimiento_ok: pieza.consentimiento_ok != null ? pieza.consentimiento_ok : false,
      notas_compliance: pieza.notas_compliance != null ? pieza.notas_compliance : null,
      brief: brief,
    }
  });
}
return out;
